{
  "id": 62,
  "knowledge": "Networked Mimicry Risk",
  "description": "Flags traders suspected of peer mimicry who are also part of an identified potential collusion network.",
  "definition": "A trader flagged for Peer Mimicry Suspicion  AND associated with a Collusion Network Indicator ."
}

{
  "id": 6,
  "knowledge": "Investigation Intensity Index (III)",
  "description": "Combines behavioral and network analysis scores from an investigation.",
  "definition": "III = (0.6 \\times \\text{behansc}) + (0.4 \\times \\text{netansc})"
}

{
  "id": 50,
  "knowledge": "Investigation Compliance Risk Index (ICRI)",
  "description": "Combines the weighted investigation score with the inverse compliance health score, highlighting cases that are both problematic and under intense investigation.",
  "definition": "ICRI = \\text{WIS} \\times (1 - \\text{CHS}) \\\\ \\text{where WIS is Weighted Investigation Score  and CHS is Compliance Health Score .}"
}

{
  "id": 55,
  "knowledge": "Capital-Adjusted Investigation Intensity (CAII)",
  "description": "Normalizes the investigation intensity index by the trader's account balance, showing investigation focus relative to trader size.",
  "definition": "CAII = \\frac{\\text{III}}{\\text{Max}(1000, \\text{acctbal})} \\\\ \\text{where III is Investigation Intensity Index .}"
}

{
  "id": 49,
  "knowledge": "Peer Mimicry Suspicion",
  "description": "Flags traders whose behavior closely matches peers but deviates little from known patterns, potentially mimicking a risky group.",
  "definition": "A trader with a low Pattern Anomaly Score (PAS)  (e.g., < 0.1) BUT a high peercorr (e.g., > 0.7), suggesting potential mimicry rather than independent strategy, possibly following a group engaged in problematic behavior."
}

{
  "id": 13,
  "knowledge": "Collusion Network Indicator",
  "description": "Suggests potential collusion based on investigation details.",
  "definition": "A case indicates potential collusion if `tcirclesz` > 5 AND `grpbehsc` > 0.6 AND `commpat` is 'Regular'."
}

